<?php
declare(strict_types=1);require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/auth.php';$u=require_student();$pdo=db();$error=null;$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');if($name==='')throw new RuntimeException('Nome obrigatório.');$pdo->beginTransaction();$pdo->prepare("UPDATE app_users SET name=:n,email=:e,updated_at=NOW() WHERE id=:i")->execute(['n'=>$name,'e'=>$email?:null,'i'=>$u['id']]);$pdo->prepare("UPDATE students SET name=:n,email=:e,updated_at=NOW() WHERE id=:i")->execute(['n'=>$name,'e'=>$email?:null,'i'=>$u['student_id']]);$pdo->commit();audit_log('profile_updated','app_user',$u['id']);$success='Perfil atualizado.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$s=$pdo->prepare("SELECT u.name,u.email,u.phone,u.username,s.created_at student_since FROM app_users u JOIN students s ON s.id=u.student_id WHERE u.id=:i");$s->execute(['i'=>$u['id']]);$d=$s->fetch();$pageTitle='Meu perfil';require __DIR__.'/../../templates/header.php';?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($success):?><div class="list-card"><strong><?=htmlspecialchars($success)?></strong></div><?php endif;?><div class="grid-2"><section class="panel"><h2>Dados pessoais</h2><form method="post"><?=csrf_field()?><div class="form-row"><label>Nome</label><input name="name" value="<?=htmlspecialchars($d['name'])?>" required></div><div class="form-row"><label>E-mail</label><input type="email" name="email" value="<?=htmlspecialchars($d['email']??'')?>"></div><div class="form-row"><label>Telefone</label><input value="<?=htmlspecialchars($d['phone']??'')?>" disabled></div><button class="btn btn-primary">Salvar perfil</button></form></section><section class="panel"><h2>Segurança</h2><div class="list-card"><strong>Senha</strong><p>Altere sua senha regularmente.</p><a class="btn btn-secondary" href="/change-password.php" style="margin-top:10px">Alterar senha</a></div></section></div><?php require __DIR__.'/../../templates/footer.php';?>
